const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=canvas.width,H=canvas.height;
const ui={rescued:document.getElementById('rescued'),busted:document.getElementById('busted'),score:document.getElementById('score'),hearts:document.getElementById('hearts'),bar:document.getElementById('progressBar'),progress:document.getElementById('progressText'),timer:null};
const keys=new Set();let state='title',last=0,elapsed=0,score=0,rescued=0,busted=0,shake=0;
let hero,bots,civilians,particles,attackFx,spawnClock=0,invuln=0,dashClock=0,punchClock=0,facing={x:1,y:0};
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function reset(){elapsed=0;score=0;rescued=0;busted=0;shake=0;spawnClock=0;invuln=0;dashClock=0;punchClock=0;facing={x:1,y:0};hero={x:500,y:315,r:17,hp:3,speed:210,dash:0};bots=[];civilians=[];particles=[];attackFx=[];
// Citizens wait at safe corners of the city.
[[115,165],[870,175],[125,480],[875,480],[500,510]].forEach((p,i)=>civilians.push({x:p[0],y:p[1],phase:i*1.7,r:11,rescued:false}));
for(let i=0;i<3;i++)spawnBot();updateHud();}
function spawnBot(){const side=Math.floor(rand(0,4));let x=side===0?36:side===1?964:rand(55,945),y=side===2?95:side===3?545:rand(110,530);bots.push({x,y,r:15,hp:1,stun:0,phase:rand(0,7),hit:0});}
function updateHud(){ui.rescued.innerHTML=`${rescued} <em>/ 5</em>`;ui.busted.innerHTML=`${busted} <em>/ 10</em>`;ui.score.textContent=String(score).padStart(4,'0');ui.hearts.textContent='♥'.repeat(hero?hero.hp:3)+'♡'.repeat(3-(hero?hero.hp:3));let total=rescued+busted;ui.progress.textContent=`${total} / 15`;ui.bar.style.width=`${Math.min(100,total/15*100)}%`;}
function startGame(){reset();state='playing';document.getElementById('startOverlay').style.display='none';document.getElementById('endOverlay').classList.remove('show');canvas.focus();last=performance.now();}
function endGame(win){state=win?'won':'lost';document.getElementById('resultIcon').textContent=win?'🏆':'💥';document.getElementById('resultTitle').textContent=win?'City saved!':'The city needs you!';document.getElementById('resultText').textContent=win?`You rescued ${rescued} citizens and busted ${busted} bots. Final score: ${score}.`:`You scored ${score} and saved ${rescued} citizens. Give it another shot!`;document.getElementById('endOverlay').classList.add('show');}
document.getElementById('playBtn').addEventListener('click',startGame);document.getElementById('againBtn').addEventListener('click',startGame);
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if((k==='j'||k==='z'||k==='enter')&&state==='playing')punch();if(k===' '&&state==='playing'&&dashClock<=0){hero.dash=.22;dashClock=1.35;}});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));canvas.addEventListener('pointerdown',()=>{if(state==='playing')punch();});
function punch(){if(punchClock>0)return;punchClock=.34;attackFx.push({x:hero.x+facing.x*24,y:hero.y+facing.y*24,age:0});let target=null,best=58;for(const b of bots){let dx=b.x-hero.x,dy=b.y-hero.y,d=Math.hypot(dx,dy);if(d<best){best=d;target=b;}}if(target){target.hp=0;target.stun=.3;score+=100;busted++;particlesBurst(target.x,target.y,'#ffb83d',13);shake=5;updateHud();if(rescued>=5&&busted>=10)endGame(true);}}
function particlesBurst(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(50,180);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,age:0,life:rand(.25,.65),color,size:rand(2,5)});}}
function update(dt){if(state!=='playing')return;elapsed+=dt;if(elapsed>=90){endGame(false);return;}spawnClock+=dt;if(spawnClock>2.65&&bots.length<7&&busted<10){spawnClock=0;spawnBot();}dashClock=Math.max(0,dashClock-dt);punchClock=Math.max(0,punchClock-dt);invuln=Math.max(0,invuln-dt);
let mx=0,my=0;if(keys.has('a')||keys.has('arrowleft'))mx--;if(keys.has('d')||keys.has('arrowright'))mx++;if(keys.has('w')||keys.has('arrowup'))my--;if(keys.has('s')||keys.has('arrowdown'))my++;if(mx||my){let mag=Math.hypot(mx,my);mx/=mag;my/=mag;facing={x:mx,y:my};}let speed=hero.dash>0?hero.speed*3:hero.speed;hero.dash=Math.max(0,hero.dash-dt);hero.x=clamp(hero.x+mx*speed*dt,35,W-35);hero.y=clamp(hero.y+my*speed*dt,100,H-38);
for(const c of civilians){if(c.rescued)continue;c.phase+=dt*2;if(Math.hypot(hero.x-c.x,hero.y-c.y)<29){c.rescued=true;rescued++;score+=250;particlesBurst(c.x,c.y,'#47d6aa',15);updateHud();}}
for(const b of bots){if(b.hp<=0)continue;b.phase+=dt*5;b.stun=Math.max(0,b.stun-dt);b.hit=Math.max(0,b.hit-dt);if(b.stun<=0){let dx=hero.x-b.x,dy=hero.y-b.y,d=Math.hypot(dx,dy)||1;b.x+=dx/d*82*dt;b.y+=dy/d*82*dt;}if(Math.hypot(hero.x-b.x,hero.y-b.y)<hero.r+b.r+3&&invuln<=0&&hero.dash<=0){hero.hp--;invuln=1.15;shake=8;particlesBurst(hero.x,hero.y,'#ff655b',9);updateHud();if(hero.hp<=0){endGame(false);return;}}}
bots=bots.filter(b=>b.hp>0);for(const p of particles){p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;}particles=particles.filter(p=>p.age<p.life);for(const f of attackFx)f.age+=dt;attackFx=attackFx.filter(f=>f.age<.22);shake=Math.max(0,shake-dt*20);}
const buildings=[{x:35,y:93,w:200,h:142,c:'#e6bca5',roof:'#f5d2b9',name:'BAKERY'},{x:267,y:92,w:175,h:144,c:'#a9c5cd',roof:'#c1d9df',name:'CORNER STORE'},{x:560,y:93,w:182,h:142,c:'#d4b8db',roof:'#e7d4e9',name:'PARKER PLAZA'},{x:767,y:92,w:198,h:144,c:'#a8bdad',roof:'#c0d0bd',name:'BOTANICALS'},{x:35,y:390,w:196,h:153,c:'#a9c0df',roof:'#c0d2e8',name:'CITY LIBRARY'},{x:266,y:390,w:178,h:153,c:'#dfbd9e',roof:'#f1d4b5',name:'CAFE NOVA'},{x:560,y:390,w:182,h:153,c:'#a8c9bc',roof:'#c1dfd0',name:'GREEN HOUSE'},{x:767,y:390,w:198,h:153,c:'#d8b8b2',roof:'#edcfca',name:'FIRE STATION'}];
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function drawCity(){ctx.fillStyle='#cee5d9';ctx.fillRect(0,0,W,H); // soft park-like city ground
// road grid
ctx.fillStyle='#8495a4';ctx.fillRect(0,236,W,154);ctx.fillRect(443,80,117,505);
// road borders and lane dashes
ctx.fillStyle='#f8e6ab';ctx.fillRect(0,232,W,4);ctx.fillRect(0,389,W,4);ctx.fillRect(439,80,4,505);ctx.fillRect(560,80,4,505);
ctx.fillStyle='#d9e4e6';for(let x=14;x<W;x+=55){ctx.fillRect(x,311,29,3);}for(let y=105;y<H;y+=47){ctx.fillRect(495,y,3,26);}
// crosswalks
ctx.fillStyle='#f6f7ee';for(let i=0;i<7;i++){ctx.fillRect(413+i*5,243,3,31);ctx.fillRect(564+i*5,369,3,17);}
// shrubs / planters
for(const [x,y] of [[250,249],[750,378],[453,218],[546,407],[248,374],[753,250]]){rounded(x,y,18,40,8,'#92c4a4');ctx.fillStyle='#70a982';ctx.beginPath();ctx.arc(x+9,y+8,7,0,Math.PI*2);ctx.fill();}
for(const b of buildings){ctx.fillStyle='#62788a25';ctx.fillRect(b.x+5,b.y+7,b.w,b.h);rounded(b.x,b.y,b.w,b.h,10,b.c);rounded(b.x+7,b.y+7,b.w-14,b.h-14,8,b.roof);
// roof panels and windows
ctx.fillStyle='#fff9';for(let x=b.x+20;x<b.x+b.w-15;x+=36){ctx.fillRect(x,b.y+28,17,14);ctx.fillRect(x,b.y+54,17,14);}
ctx.fillStyle='#fff5';ctx.fillRect(b.x+17,b.y+83,b.w-34,2);ctx.fillStyle='#38546b66';ctx.font='900 8px system-ui';ctx.textAlign='center';ctx.fillText(b.name,b.x+b.w/2,b.y+b.h-15);
// rooftop details
ctx.fillStyle='#71899a55';ctx.fillRect(b.x+b.w-35,b.y+20,16,11);ctx.fillRect(b.x+18,b.y+b.h-39,20,10);
}}
function drawCitizen(c){if(c.rescued)return;let bob=Math.sin(c.phase)*2;ctx.save();ctx.translate(c.x,c.y+bob);ctx.fillStyle='#243c5540';ctx.beginPath();ctx.ellipse(0,14,12,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd2a9';ctx.beginPath();ctx.arc(0,-5,7,0,Math.PI*2);ctx.fill();ctx.fillStyle=['#f08364','#6d87df','#f2a83c','#a16dcc','#3eae92'][Math.floor(c.phase/1.7+5)%5];ctx.beginPath();ctx.roundRect(-7,2,14,14,5);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(13,-11,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#35b88f';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillText('!',13,-7);ctx.restore();}

